def recursive_max(arr):
    if len(arr) == 1:
        return arr[0]

    mid = len(arr) // 2

    left_max = recursive_max(arr[:mid])
    right_max = recursive_max(arr[mid:])

    if left_max > right_max:
        return left_max

    return right_max

print(recursive_max([8, 3, 11, 5, 2]))

def divide_size(n):
    print(n)

    if n <= 1:
        return

    divide_size(n // 2)

divide_size(16)
